{
  "items": [
    {
      "name": "finprod_mem_inter_mulSupport",
      "module_name": "Mathlib.Algebra.BigOperators.Finprod",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_5} [inst : CommMonoid M] (f : α → M) (s : Set α),\n  ∏ᶠ (i : α) (_ : i ∈ s ∩ Function.mulSupport f), f i = ∏ᶠ (i : α) (_ : i ∈ s), f i"
    },
    {
      "name": "finprod_mem_mulSupport",
      "module_name": "Mathlib.Algebra.BigOperators.Finprod",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_5} [inst : CommMonoid M] (f : α → M),\n  ∏ᶠ (a : α) (_ : a ∈ Function.mulSupport f), f a = ∏ᶠ (a : α), f a"
    },
    {
      "name": "finprod_eq_prod_of_mulSupport_subset_of_finite",
      "module_name": "Mathlib.Algebra.BigOperators.Finprod",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_5} [inst : CommMonoid M] (f : α → M) {s : Set α},\n  Function.mulSupport f ⊆ s → ∀ (hs : s.Finite), ∏ᶠ (i : α), f i = ∏ i ∈ hs.toFinset, f i"
    },
    {
      "name": "Finsupp.prod_fintype",
      "module_name": "Mathlib.Algebra.BigOperators.Finsupp.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_8} {N : Type u_10} [inst : Zero M] [inst_1 : CommMonoid N] [inst_2 : Fintype α]\n  (f : α →₀ M) (g : α → M → N), (∀ (i : α), g i 0 = 1) → f.prod g = ∏ i, g i (f i)"
    },
    {
      "name": "Finsupp.prod",
      "module_name": "Mathlib.Algebra.BigOperators.Finsupp.Basic",
      "kind": "definition",
      "type": "{α : Type u_1} → {M : Type u_8} → {N : Type u_10} → [inst : Zero M] → [CommMonoid N] → (α →₀ M) → (α → M → N) → N"
    },
    {
      "name": "hasProd_fintype_support",
      "module_name": "Mathlib.Topology.Algebra.InfiniteSum.Defs",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_2} [inst : CommMonoid α] [inst_1 : TopologicalSpace α] [inst_2 : Fintype β] (f : β → α)\n  (L : SummationFilter β) [L.HasSupport] [inst_4 : DecidablePred fun x => x ∈ L.support],\n  HasProd f (∏ b ∈ L.support.toFinset, f b) L"
    },
    {
      "name": "DFinsupp.prod_eq_prod_fintype",
      "module_name": "Mathlib.Data.DFinsupp.BigOperators",
      "kind": "theorem",
      "type": "∀ {ι : Type u} {γ : Type w} {β : ι → Type v} [inst : DecidableEq ι] [inst_1 : Fintype ι] [inst_2 : (i : ι) → Zero (β i)]\n  [inst_3 : (i : ι) → (x : β i) → Decidable (x ≠ 0)] [inst_4 : CommMonoid γ] (v : Π₀ (i : ι), β i)\n  {f : (i : ι) → β i → γ}, (∀ (i : ι), f i 0 = 1) → v.prod f = ∏ i, f i (DFinsupp.equivFunOnFintype v i)"
    },
    {
      "name": "DFinsupp.prod",
      "module_name": "Mathlib.Data.DFinsupp.BigOperators",
      "kind": "definition",
      "type": "{ι : Type u} →\n  {γ : Type w} →\n    {β : ι → Type v} →\n      [DecidableEq ι] →\n        [inst : (i : ι) → Zero (β i)] →\n          [(i : ι) → (x : β i) → Decidable (x ≠ 0)] → [CommMonoid γ] → (Π₀ (i : ι), β i) → ((i : ι) → β i → γ) → γ"
    },
    {
      "name": "tprod_eq_prod'",
      "module_name": "Mathlib.Topology.Algebra.InfiniteSum.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_2} [inst : CommMonoid α] [inst_1 : TopologicalSpace α] {f : β → α} {L : SummationFilter β}\n  [L.LeAtTop] {s : Finset β}, Function.mulSupport f ⊆ ↑s → ∏'[L] (b : β), f b = ∏ b ∈ s, f b"
    },
    {
      "name": "finprod_eq_prod_of_mulSupport_subset",
      "module_name": "Mathlib.Algebra.BigOperators.Finprod",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_5} [inst : CommMonoid M] (f : α → M) {s : Finset α},\n  Function.mulSupport f ⊆ ↑s → ∏ᶠ (i : α), f i = ∏ i ∈ s, f i"
    }
  ]
}
